(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const bookSource=window.TERRA.sources.find(s=>s.id==='journey');if(bookSource)bookSource.note='设定集涵盖源石、天灾、矿石病、科技、种族、国家与组织，并以作者正文、凯尔希批注及罗德岛档案共同叙述。本卷据用户提供的全文TXT转录作原创转述，具体采用章节和转录局限见本页校读记录。此链接为官方公开介绍。';
 const data=()=>window.JOURNEY_REFERENCE||{meta:{},chapters:[],personNotes:[]};
 const canonical=id=>window.PERSON_BIOGRAPHIES.recordToPerson[id]||id;
 function get(p){return data().personNotes.filter(n=>n.personId===canonical(p.id));}
 function textOf(p){return get(p).map(n=>[n.title,n.period,n.body].join(' ')).join(' ');}
 const refs=rows=>(rows||[]).map(r=>`<a href="${esc(r.url)}"${/^https?:/.test(r.url)?' target="_blank" rel="noopener noreferrer"':''}>${esc(r.label)} ↗</a>`).join('；');
 const relatedRegion=id=>window.TERRA.regions.find(r=>r.id===id);
 function render(p){const notes=get(p);if(!notes.length)return '';const names=window.ROSTER_RENDER.all.map(r=>r.name).filter(n=>n.length>=2);return `<section class="journey-person-section" id="life-journey"><div class="eyebrow">TERRA: A JOURNEY / PERSON & CONTEXT</div><h2>设定集中的人物补记</h2><p class="journey-context">以下按《大地巡旅》的记述时点，补充人物所处的制度、生活与关系背景。书中作者、批注者及罗德岛档案各有观察范围。</p>${notes.map(n=>`<article class="journey-person-note chapter-section"><div class="period-label">${esc(n.period)}</div><h3>${esc(n.title)}</h3>${n.body.split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${window.REGION_UI.inline(t,names)}</p>`).join('')}<div class="biography-evidence">材料：${refs(n.refs)} <span class="origin-evidence-tag">设定集文本转录</span></div>${relatedRegion(n.region)?`<a class="journey-region-link" href="#/atlas/${n.region}">${esc(relatedRegion(n.region).name)} · 地区历史与事件 ↗</a>`:''}</article>`).join('')}</section>`;}
 function raceLinks(p){const entries=window.TERRA_RACES?.entries||[];const basic=window.PROFILE_UI?.get(p.id)?.options.flatMap(o=>o.basic.filter(f=>f.label==='种族').map(f=>f.value))||[];const rows=entries.filter(r=>r.profileNames?.some(n=>basic.includes(n))||r.relatedNames?.includes(p.name));return rows.length?`<div class="journey-race-links"><span>相关种族专题</span>${rows.map(r=>`<a href="#/races/${r.id}">${esc(r.name)} ↗</a>`).join('')}</div>`:'';}
 function raceSearch(q,prefs){const rows=(window.TERRA_RACES?.entries||[]).filter(r=>[r.name,r.en,r.summary,prefs.full?r.sections.map(s=>s.body).join(' '):''].join(' ').toLowerCase().includes(q.toLowerCase())).slice(0,8);return rows.length?`<div class="eyebrow" style="margin:23px 0 12px">种族专题</div>${rows.map(r=>`<a class="search-result" href="#/races/${r.id}" data-close-dialog="search-dialog"><small>族群历史与文化</small><h3>${esc(r.name)}</h3><p>${esc(r.summary)}</p></a>`).join('')}`:'';}
 function sources(){const d=data(),m=d.meta;return `<section class="source-section journey-reference" id="journey-reference"><h2>《大地巡旅》校读记录</h2><p>本次依据用户提供的《TERRA: A JOURNEY／大地巡旅》TXT转录，校补各地区历史、人物背景与种族专题。地区沿革采用书中可辨识的建制、战争和社会变迁，人物补记与游戏的后续经历分别标明时点。</p><p>参考文本有 OCR 错字、跨栏串行及混入正文的批注。章节与印刷页区间按文本目录识别，尚未以原版影印逐页核校；不能把残缺字句还原成未经证实的事实。书内作者的历史判断、凯尔希批注及罗德岛档案保留各自的叙述立场。具体阶段列出采用章节，公开网页提供原创转述与引用目录。</p><div class="journey-source-stats"><span>${m.regions||0} 个地区与组织校补</span><span>${m.personNotes||0} 篇人物补记</span><span>${window.TERRA_RACES?.meta.count||window.TERRA_RACES?.entries.length||0} 篇种族专题</span></div><p>《大地巡旅》定稿时点与游戏后续活动各有范围；本卷据游戏原文续写后续事件。谢拉格的对外开放与三族会议属于不同节点，不能仅凭年表条目把整个改革过程压成同一年。</p><div class="journey-chapter-list">${d.chapters.map(c=>`<details class="journey-chapter" id="${esc(c.id.startsWith('journey-')?c.id:'journey-'+c.id)}"><summary>${esc(c.title)} <span>${esc(c.chapter)} · ${esc(c.pages)}</span></summary><p>${esc(c.scope||'采用本章可辨识的历史、制度及社会生活材料，并与所引游戏剧情对读。')}</p>${(Array.isArray(c.notes)?c.notes:c.notes?[c.notes]:[]).map(n=>`<p>${esc(n)}</p>`).join('')}<p class="journey-line-range">转录定位：第 ${c.lineStart}–${c.lineEnd} 行。此行号用于定位用户提供的 TXT，不是印刷书页。</p>${relatedRegion(c.region)?`<a href="#/atlas/${c.region}">${esc(relatedRegion(c.region).name)}纪事 ↗</a>`:'<a href="#/races">进入种族专题 ↗</a>'}</details>`).join('')}</div><p><a href="journey-meta.json" target="_blank" rel="noopener noreferrer">采用范围与文本版本摘要 ↗</a></p></section>`;}
 window.JOURNEY_UI={get,textOf,render,raceLinks,raceSearch,sources};
})();
